param(
    [string]$GameDir = '',
    [switch]$Uninstall,
    [switch]$NoPause
)
# World Apart (不问凡尘) - Thai mod installer. Windows PowerShell 5.1 compatible.
# Generated by tools/make_dist.py - do not edit the FILES table by hand.
#
# The mod ships PATCHES, not game files. tools\ThaiModPatcher.cs rebuilds every modded bundle
# from the player's own original bundle + patches\<name>.wtp; the result is checked by sha256
# before it replaces anything. Originals are kept in <game>\ThaiMod_backup for uninstall.
$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}

$ModVersion = 'v0.2'
$AppId = '4209920'
$ExpectedBuild = '26646193'
$RelDir = 'WorldApart_Data\StreamingAssets\yoo\DefaultPackage'
$BackupName = 'ThaiMod_backup'
$FILES = @(
    @{ Name = 'e00c0a8b32ed219ae2ca092b6494e645.bundle'; Label = 'ข้อความภาษาไทย'; Orig = '9b5b1c8426cd13dac149f40d22dee6f7da067fde9cabed1fa32e8b3f572a5c77'; Mod = '14c3592e1288ab7f358886a4c4d7d93bdcf2a55973497038b46491d8da03e6a9';
       Patch = 'e00c0a8b32ed219ae2ca092b6494e645.wtp'; PatchSha = 'd2b3aefc3279c89dd8dfa0c91d0b1f00f1717a6ec973826463ccbaa9f89457e6'; Old = @('ad92b7daea75048b9ae80d2b357984b7d24689e17aeb34fe207662c9cf5dbb34') },
    @{ Name = '93df5ce1601125a448e2d6acdeec7357.bundle'; Label = 'ฟอนต์ภาษาไทย'; Orig = 'ee3f173836c41cc5be26e6480f270a768d1d2b59f5480ee98cb69ed41f570686'; Mod = '55ef7bd28298a0507499f397385578b971dd0d345a06ef79029495b69216692b';
       Patch = '93df5ce1601125a448e2d6acdeec7357.wtp'; PatchSha = '1015a6b256b53029e440d9a0fb47794badb4ffb3a7df4b1c6e97e5406d1117b2'; Old = @('f4f42a08da454242eec89c13a3d17d403046432ba5eddcf1c76be42c6d74a075') }
)
$ModRoot = Split-Path -Parent $PSScriptRoot

function Say($msg, $color = 'Gray') { Write-Host $msg -ForegroundColor $color }
function Done($code) {
    if (-not $NoPause) { Say ''; Read-Host 'กด Enter เพื่อปิดหน้าต่างนี้' | Out-Null }
    exit $code
}
function Sha($p) { (Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLower() }
function Is-Mod($f, $h) { ($h -eq $f.Mod) -or ($f.Old -contains $h) }

function Find-Game {
    $libs = @()
    foreach ($key in 'HKCU:\Software\Valve\Steam', 'HKLM:\SOFTWARE\WOW6432Node\Valve\Steam') {
        try {
            $sp = (Get-ItemProperty -Path $key -ErrorAction Stop)
            foreach ($v in @($sp.SteamPath, $sp.InstallPath)) { if ($v) { $libs += ($v -replace '/', '\') } }
        } catch {}
    }
    foreach ($root in @($libs)) {
        $vdf = Join-Path $root 'steamapps\libraryfolders.vdf'
        if (Test-Path -LiteralPath $vdf) {
            foreach ($m in [regex]::Matches((Get-Content -LiteralPath $vdf -Raw), '"path"\s+"([^"]+)"')) {
                $libs += ($m.Groups[1].Value -replace '\\\\', '\')
            }
        }
    }
    foreach ($lib in ($libs | Select-Object -Unique)) {
        $acf = Join-Path $lib "steamapps\appmanifest_$AppId.acf"
        if (Test-Path -LiteralPath $acf) {
            $txt = Get-Content -LiteralPath $acf -Raw
            $dir = [regex]::Match($txt, '"installdir"\s+"([^"]+)"').Groups[1].Value
            $script:FoundBuild = [regex]::Match($txt, '"buildid"\s+"([^"]+)"').Groups[1].Value
            $p = Join-Path $lib "steamapps\common\$dir"
            if (Test-Path -LiteralPath (Join-Path $p 'WorldApart.exe')) { return $p }
        }
    }
    return $null
}

Say "=== มอดภาษาไทย World Apart (不问凡尘) เวอร์ชัน $ModVersion ===" 'Cyan'

if (-not $GameDir) { $GameDir = Find-Game }
if (-not $GameDir) {
    Say 'หาโฟลเดอร์เกมอัตโนมัติไม่เจอ' 'Yellow'
    Say 'วิธีหา: Steam > คลิกขวาที่เกม > Manage > Browse local files แล้วคัดลอกที่อยู่โฟลเดอร์มาวาง'
    if ($NoPause) { Done 2 }
    $GameDir = (Read-Host 'วางที่อยู่โฟลเดอร์เกม (ที่มีไฟล์ WorldApart.exe) แล้วกด Enter').Trim('"', ' ')
}
if (-not (Test-Path -LiteralPath (Join-Path $GameDir 'WorldApart.exe'))) {
    Say "ไม่พบ WorldApart.exe ใน: $GameDir" 'Red'
    Done 2
}
Say "โฟลเดอร์เกม: $GameDir"
if ($script:FoundBuild -and $script:FoundBuild -ne $ExpectedBuild) {
    Say "หมายเหตุ: เวอร์ชันเกมใน Steam ($($script:FoundBuild)) ต่างจากที่มอดนี้ทำไว้ ($ExpectedBuild) จะตรวจไฟล์ต่อเพื่อความแน่ใจ" 'Yellow'
}

if (Get-Process -Name 'WorldApart' -ErrorAction SilentlyContinue) {
    Say 'เกมกำลังเปิดอยู่ กรุณาปิดเกมก่อน แล้วรันใหม่อีกครั้ง' 'Red'
    Done 3
}

$dataDir = Join-Path $GameDir $RelDir
$backupDir = Join-Path $GameDir $BackupName

# ---- check every file BEFORE changing anything --------------------------------------------
# original = untouched game file, modded = this version, oldmod = an earlier version of this mod
$plan = @()
foreach ($f in $FILES) {
    $target = Join-Path $dataDir $f.Name
    $state = 'missing'
    if (Test-Path -LiteralPath $target) {
        $h = Sha $target
        if ($h -eq $f.Orig) { $state = 'original' }
        elseif ($h -eq $f.Mod) { $state = 'modded' }
        elseif ($f.Old -contains $h) { $state = 'oldmod' }
        else { $state = 'other' }
    }
    $plan += [pscustomobject]@{ F = $f; Target = $target; State = $state; Bak = (Join-Path $backupDir $f.Name) }
}

if ($Uninstall) {
    Say '--- ถอนการติดตั้ง ---' 'Cyan'
    foreach ($p in $plan) {
        if ($p.State -eq 'modded' -or $p.State -eq 'oldmod') {
            if ((Test-Path -LiteralPath $p.Bak) -and ((Sha $p.Bak) -eq $p.F.Orig)) {
                Copy-Item -LiteralPath $p.Bak -Destination $p.Target -Force
                if ((Sha $p.Target) -ne $p.F.Orig) { Say "คืนไฟล์ไม่สำเร็จ: $($p.F.Name)" 'Red'; Done 4 }
                Say "คืนไฟล์เดิมแล้ว: $($p.F.Label)" 'Green'
            } else {
                Say "ไม่พบไฟล์สำรองของ $($p.F.Label) - ให้ใช้ Steam > Properties > Installed Files > Verify integrity of game files" 'Yellow'
            }
        } else {
            Say "$($p.F.Label): ไม่ได้ติดตั้งมอดอยู่ (ข้าม)"
        }
    }
    $still = @($FILES | Where-Object {
        $t = Join-Path $dataDir $_.Name
        (Test-Path -LiteralPath $t) -and (Is-Mod $_ (Sha $t))
    })
    if ($still.Count -eq 0 -and (Test-Path -LiteralPath $backupDir)) { Remove-Item -LiteralPath $backupDir -Recurse -Force }
    Say 'ถอนการติดตั้งเสร็จแล้ว เกมกลับเป็นต้นฉบับ' 'Green'
    Done 0
}

$bad = @($plan | Where-Object { $_.State -eq 'missing' -or $_.State -eq 'other' })
if ($bad.Count -gt 0) {
    Say 'หยุดการติดตั้ง: ไฟล์เกมไม่ตรงกับเวอร์ชันที่มอดนี้รองรับ' 'Red'
    foreach ($b in $bad) { Say "  - $($b.F.Label): $($b.State)" 'Red' }
    Say 'สาเหตุที่พบบ่อย: เกมเพิ่งอัปเดต ต้องรอมอดเวอร์ชันใหม่ (ไม่ได้แก้ไขไฟล์ใด ๆ ของเกม)' 'Yellow'
    Done 5
}
$todo = @($plan | Where-Object { $_.State -eq 'original' -or $_.State -eq 'oldmod' })
if ($todo.Count -eq 0) {
    Say 'มอดภาษาไทยเวอร์ชันนี้ติดตั้งอยู่แล้ว ไม่ต้องทำอะไรเพิ่ม' 'Green'
    Done 0
}

# ---- patch files present and intact? --------------------------------------------------------
foreach ($p in $todo) {
    $patch = Join-Path $ModRoot ("patches\" + $p.F.Patch)
    if (-not (Test-Path -LiteralPath $patch) -or (Sha $patch) -ne $p.F.PatchSha) {
        Say "ไฟล์มอดเสียหายหรือไม่ครบ: patches\$($p.F.Patch) - ลองดาวน์โหลดและแตกไฟล์ zip ใหม่" 'Red'
        Done 6
    }
}

# ---- back up the originals (an old-mod file means the backup must already be there) ---------
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
foreach ($p in $todo) {
    $ok = (Test-Path -LiteralPath $p.Bak) -and ((Sha $p.Bak) -eq $p.F.Orig)
    if (-not $ok -and $p.State -eq 'original') {
        Copy-Item -LiteralPath $p.Target -Destination $p.Bak -Force
        $ok = ((Sha $p.Bak) -eq $p.F.Orig)
    }
    if (-not $ok) {
        if ($p.State -eq 'oldmod') {
            Say "ไม่พบไฟล์สำรองต้นฉบับของ $($p.F.Label) (ติดตั้งมอดเวอร์ชันเก่าไว้)" 'Red'
            Say 'แก้: Steam > คลิกขวาที่เกม > Properties > Installed Files > Verify integrity of game files แล้วรัน install.bat ใหม่' 'Yellow'
        } else {
            Say 'สำรองไฟล์เดิมไม่สำเร็จ - หยุดการติดตั้ง (ยังไม่ได้แก้ไฟล์เกม)' 'Red'
        }
        if (-not (Get-ChildItem -LiteralPath $backupDir -Force)) { Remove-Item -LiteralPath $backupDir -Force }
        Done 7
    }
}

# ---- build the Thai files from the originals + patches -------------------------------------
try {
    Add-Type -Path (Join-Path $PSScriptRoot 'ThaiModPatcher.cs')
} catch {
    Say "เตรียมตัวติดตั้งไม่สำเร็จ (คอมไพล์ ThaiModPatcher.cs ไม่ได้): $($_.Exception.Message)" 'Red'
    Done 9
}
$installed = @()
foreach ($p in $todo) {
    $patch = Join-Path $ModRoot ("patches\" + $p.F.Patch)
    $tmp = $p.Target + '.thaimod_tmp'
    Say "กำลังสร้าง$($p.F.Label) ... (ใช้เวลาไม่กี่วินาที)"
    $err = $null
    try {
        [ThaiModPatcher]::Build($p.Bak, $patch, $tmp)
        if ((Sha $tmp) -ne $p.F.Mod) { $err = 'ไฟล์ที่สร้างได้ไม่ตรงกับที่ควรเป็น' }
        else { Move-Item -LiteralPath $tmp -Destination $p.Target -Force }
    } catch {
        $err = $_.Exception.Message
    }
    if (-not $err -and (Sha $p.Target) -ne $p.F.Mod) { $err = 'ตรวจไฟล์หลังติดตั้งไม่ผ่าน' }
    if ($err) {
        if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force }
        # put back everything this run touched, so the game is never left half-modded
        foreach ($q in @($installed) + @($p)) { Copy-Item -LiteralPath $q.Bak -Destination $q.Target -Force }
        Say "ติดตั้ง$($p.F.Label)ไม่สำเร็จ: $err" 'Red'
        Say 'คืนไฟล์ที่แก้ไปแล้วในรอบนี้ให้แล้ว' 'Yellow'
        Done 8
    }
    $installed += $p
    Say "ติดตั้งแล้ว: $($p.F.Label)" 'Green'
}
Say ''
Say 'ติดตั้งมอดภาษาไทยเสร็จแล้ว!' 'Green'
Say 'ในเกมให้ไปที่ ตั้งค่า (Settings) > ภาษา (Language) แล้วเลือก "ภาษาไทย" (ช่องเดิมของ English)' 'Cyan'
Done 0
